CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE cities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,country_code char(2) NOT NULL DEFAULT 'CN',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE districts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city_id uuid NOT NULL REFERENCES cities(id),name text NOT NULL,UNIQUE(city_id,name));
CREATE TABLE communities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),district_id uuid NOT NULL REFERENCES districts(id),slug text UNIQUE NOT NULL,name text NOT NULL,status text NOT NULL CHECK(status IN('open','coming_soon','paused')),scene_config jsonb NOT NULL DEFAULT '{}',operation_rules jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE community_members(community_id uuid NOT NULL REFERENCES communities(id),user_id uuid NOT NULL,role text NOT NULL DEFAULT 'member',joined_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(community_id,user_id));
CREATE TABLE community_marketplaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),community_id uuid NOT NULL REFERENCES communities(id),name text NOT NULL,status text NOT NULL DEFAULT 'open',UNIQUE(community_id,name));
CREATE TABLE community_stalls(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),community_id uuid NOT NULL REFERENCES communities(id),marketplace_id uuid REFERENCES community_marketplaces(id),name text NOT NULL,operator_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(community_id,id));
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),community_id uuid NOT NULL REFERENCES communities(id),stall_id uuid,seller_id uuid NOT NULL,title text NOT NULL,description text,category text NOT NULL,price numeric(12,2) NOT NULL CHECK(price>=0),status text NOT NULL DEFAULT 'active',location_text text,latitude numeric(10,7),longitude numeric(10,7),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(community_id,stall_id) REFERENCES community_stalls(community_id,id));
CREATE INDEX products_community_status_created ON products(community_id,status,created_at DESC);
CREATE TABLE user_wants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),community_id uuid NOT NULL REFERENCES communities(id),user_id uuid NOT NULL,title text NOT NULL,detail text,budget_max numeric(12,2),status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recommendations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),community_id uuid NOT NULL REFERENCES communities(id),user_id uuid NOT NULL,product_id uuid NOT NULL REFERENCES products(id),source_community_id uuid NOT NULL REFERENCES communities(id),mode text NOT NULL CHECK(mode IN('local','nearby','all')),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),community_id uuid REFERENCES communities(id),scope text NOT NULL CHECK(scope IN('platform','community')),agent_role text NOT NULL,task_type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'queued',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE trade_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),community_id uuid NOT NULL REFERENCES communities(id),conversation_id uuid NOT NULL,sender_id uuid NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
-- Cross-community searches must filter communities.status='open' and return source community metadata.